const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const wilmingtonPoint = ee.Geometry.Point([-77.9447, 34.2257]); // Wilmington, North Carolina
  const aoi = wilmingtonPoint.buffer(10000); // 10km buffer around Wilmington
  const startDate = '2018-01-01';
  const endDate = '2018-12-31';
  const targetRainfallInches = 90;
  const mmToInches = 25.4; // 1 inch = 25.4 mm

  // 2. Data Acquisition
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(aoi);

  // Check for C1: Empty Collection
  const collectionSize = await chirps.size().getInfo();
  if (collectionSize === 0) {
    console.log(`No CHIRPS images found for ${startDate} to ${endDate} in the specified area.`);
    console.log("C1");
    return;
  }
  console.log(`CHIRPS images found: ${collectionSize}`);

  // Sum the daily precipitation for the entire period
  // The 'precipitation' band contains rainfall in millimeters.
  const totalPrecipitationImage = chirps.sum();

  // 3. Processing: Calculate valid pixels
  // Use a relatively large scale for accuracy and to avoid memory issues.
  const scale = 5000;

  // Get pixel count to check for C2
  const pixelCountDict = await totalPrecipitationImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const validPixels = pixelCountDict['precipitation'];

  if (validPixels === 0) {
    console.log("No valid pixels remaining after summing precipitation for the region.");
    console.log("C2");
    return;
  }
  console.log(`Valid pixels contributing to sum: ${validPixels}`);

  // 4. Calculation
  // Reduce the summed image to get the mean precipitation over the AOI
  const meanPrecipitationDict = await totalPrecipitationImage.reduceRegion({
    reducer: ee.Reducer.mean(), // Mean over the AOI, as CHIRPS is a grid
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const totalPrecipitationMM = meanPrecipitationDict['precipitation'];

  // Check for C3: Calculation Failure (Null/NaN)
  if (totalPrecipitationMM === null || isNaN(totalPrecipitationMM)) {
    console.log("Calculation failed: Total precipitation is null or NaN.");
    console.log("C3");
    return;
  }

  const totalPrecipitationInches = totalPrecipitationMM / mmToInches;

  // 5. Validation & Final Answer
  console.log(`Total precipitation (mm) for Wilmington in 2018: ${totalPrecipitationMM.toFixed(2)}`);
  console.log(`Total precipitation (inches) for Wilmington in 2018: ${totalPrecipitationInches.toFixed(2)}`);
  console.log(`Target rainfall: ${targetRainfallInches} inches`);

  if (totalPrecipitationInches >= targetRainfallInches) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
